// Deja pasar solo un mensaje NUEVO que escribió la persona (no el bot, no una nota interna).
// Si no corresponde, devuelve nada y el flujo termina acá.
const b = $('Aviso de Chatwoot').first().json.body || {};
const tipo = b.message_type;
const esEntrante = tipo === 'incoming' || tipo === 0;
if (b.event !== 'message_created' || !esEntrante || b.private === true || !b.conversation?.id) return [];
return [{ json: { conversacion: b.conversation.id } }];

// Decide qué hace el bot con UN mensaje nuevo. No manda nada: solo arma el pedido.
// Lee la configuración, los textos y el aviso de Chatwoot. Todo lo de la conversación
// (estado, paso, teléfono) viene en el aviso: el token de un bot de Chatwoot 4.12 no puede leerla aparte.
const cfg = $('Configuración').first().json;
const T = $('Textos').first().json;
const aviso = $('Aviso de Chatwoot').first().json.body || {};
const conv = aviso.conversation || {};

const normalizar = (t) => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const soloDigitos = (t) => String(t || '').replace(/\D/g, '');

const modo = normalizar(cfg.MODO);
const texto = normalizar(aviso.content);
const adjuntos = Array.isArray(aviso.attachments) ? aviso.attachments : [];
const atributos = (conv.custom_attributes && typeof conv.custom_attributes === 'object') ? conv.custom_attributes : {};
const paso = String(atributos.taller_paso || '');
const telefono = soloDigitos(conv.meta?.sender?.phone_number);
const estado = String(conv.status || '');
const bandeja = Number(conv.inbox_id ?? aviso.inbox?.id);

// Lo que sale de acá.
const salida = (accion, extra = {}) => [{ json: {
  accion,                       // 'responder' | 'solo_pasar' | 'nada'
  conversacion: conv.id,
  texto: '',                    // texto a mandar (uno por mensaje)
  mandarQR: false,
  atributosNuevos: null,        // custom_attributes completos si cambia el paso; null si no
  pasarASergio: false,
  motivo: '',
  ...extra,
} }];

// 1. Solo la bandeja configurada y solo conversaciones que todavía son del bot ("pendiente").
if (!conv.id || bandeja !== Number(cfg.BANDEJA_ID)) return salida('nada', { motivo: 'otra bandeja o sin conversación' });
if (estado !== 'pending') return salida('nada', { motivo: 'la conversación ya la atiende una persona' });

// 2. En modo prueba, el bot solo le contesta al teléfono de prueba. A todos los demás
//    los pasa enseguida a "abierto", así siguen llegando a Sergio como hoy.
if (modo !== 'real') {
  const prueba = soloDigitos(cfg.TELEFONO_PRUEBA);
  if (!prueba || telefono !== prueba) return salida('solo_pasar', { pasarASergio: true, motivo: 'modo prueba: no es el teléfono de prueba' });
}

// 3. Pedidos de baja: no se contesta (la plataforma registra la baja) y pasa a Sergio.
//    Mismas palabras que lib/whatsapp-onia/baja.ts de onia-platform.
const RE_BAJA = new RegExp([
  '^\\s*(?:stop|baja|unsubscribe|bajarme)\\s*[!.]*$',
  '^\\s*no,?\\s*gracias\\s*[!.]*$',
  '\\bstop\\b',
  '\\b(?:desuscrib\\w+|dar de baja|darme de baja|dame de baja|borrame)\\b',
  '\\bno me (?:escribas|escriban|escriba|contactes|contacten|molestes|molesten|molestar|mandes|manden|mandeis|envies|envien|llames|llamen)\\b',
  '\\bno quiero que me (?:\\w+\\s+){0,2}(?:escrib\\w+|contact\\w+|molest\\w+|llam\\w+|mand\\w+|envi\\w+)\\b',
  '\\bdej(?:a|e)n?me en paz\\b',
  '\\bdej(?:a|e)n?me de (?:escribir|molestar|mandar|escribirme|joder)\\b',
  '\\bno me interesa\\b(?!\\s+(?:el|la|los|las|tu|su|ese|esa|eso|este|esta)\\b)',
].join('|'));
if (RE_BAJA.test(texto)) return salida('solo_pasar', { pasarASergio: true, motivo: 'pedido de baja' });

// El paso del taller se guarda en un atributo de la conversación (taller_paso), porque el token
// de un bot de Chatwoot 4.12 no puede poner etiquetas. Los pasos van en orden.
const ORDEN = ['', 'consulta', 'precio', 'qr', 'comprobante'];
const E = { consulta: 'consulta', precio: 'precio', qr: 'qr', comprobante: 'comprobante' };
const tiene = (e) => ORDEN.indexOf(paso) >= ORDEN.indexOf(e);
// Se manda el objeto entero, porque la API reemplaza todos los atributos.
const con = (nuevo) => ({ ...atributos, taller_paso: nuevo });

// Arma la respuesta. En modo real, un texto con algo [ENTRE CORCHETES] sin completar
// no sale: se manda la frase de derivar y pasa a Sergio.
const responder = (clave, extra = {}) => {
  let t = String(T[clave] || '');
  if (!t.trim()) return salida('solo_pasar', { pasarASergio: true, motivo: `texto vacío: ${clave}` });
  if (modo === 'real' && /\[[^\]]+\]/.test(t)) {
    return salida('responder', { texto: T.DERIVAR, pasarASergio: true, motivo: `texto sin completar: ${clave}` });
  }
  return salida('responder', { texto: t, motivo: clave, ...extra });
};

const ES_TALLER = /\b(taller|claude|workshop|clases?|curso|0 a 100|cero a cien|inscrib\w*|vengo de la web)\b/;
const QUIERE_PERSONA = /\b(sergio|humano|persona|asesor|hablar con alguien|llamada)\b/;
const QUIERE_QR = /\b(qr|pagar|pago|reserv\w*|me anoto|anotame|inscribime|quiero (?:mi lugar|inscribirme|entrar|reservar)|dale|si|claro|ok|okey|listo)\b/;
const PREGUNTA_PRECIO = /\b(precio|cuanto|costo|cuesta|vale|info|informacion)\b/;

// 4. Primer mensaje de la conversación, todavía sin paso del taller.
if (!tiene(E.consulta)) {
  // Si no habla del taller (por ejemplo, alguien de la plataforma), no se mete: pasa a Sergio.
  if (!ES_TALLER.test(texto)) return salida('solo_pasar', { pasarASergio: true, motivo: 'no menciona el taller' });
  return responder('SALUDO', { atributosNuevos: con(E.consulta) });
}

// 5. Foto o PDF: se toma como comprobante y pasa a Sergio, que verifica en el banco.
if (adjuntos.length > 0) return responder('COMPROBANTE', { atributosNuevos: con(E.comprobante), pasarASergio: true });

// 6. Pide hablar con alguien.
if (QUIERE_PERSONA.test(texto)) return responder('DERIVAR', { pasarASergio: true });

// Dice que no le interesa algo: mejor que lo vea Sergio.
if (/\bno me interesa\b/.test(texto)) return responder('DERIVAR', { pasarASergio: true });

// 7. Preguntas frecuentes.
if (/\bcertificad\w*/.test(texto)) return responder('DERIVAR', { pasarASergio: true });
if (/\b(grabad\w*|grabacion\w*|no puedo ir|si falto)\b/.test(texto)) return responder('FAQ_GRABADO');
if (/\b(devolucion|devuelven|reembolso)\b/.test(texto)) return responder('FAQ_DEVOLUCION');
if (/\b(descuento|cuotas?|promo\w*|rebaja)\b/.test(texto)) return responder('FAQ_DESCUENTO');
if (/\b(por clase|cada clase)\b/.test(texto)) return responder('FAQ_POR_CLASE');
if (/\b(saber algo|conocimientos?|desde cero|nunca use|no se nada|principiante)\b/.test(texto)) return responder('FAQ_SABER');
if (/\b(otra persona|nombre de|a nombre)\b/.test(texto) && tiene(E.qr)) return responder('FAQ_TITULAR');

// 8. Ya tiene el QR y escribe otra cosa: pasa a Sergio.
if (tiene(E.qr)) return responder('DERIVAR', { pasarASergio: true });

// 9. Ya vio el precio y dice que sí: QR.
if (tiene(E.precio) && QUIERE_QR.test(texto)) {
  const hayImagen = String(cfg.QR_IMAGEN_URL || '').trim() !== '';
  // Sin imagen configurada, el texto sale igual y Sergio adjunta el QR a mano.
  return responder('QR', { atributosNuevos: con(E.qr), mandarQR: hayImagen, pasarASergio: !hayImagen });
}

// 10. Contesta el saludo (trabajo, estudios, negocio) o pregunta el precio: precio.
if (!tiene(E.precio)) return responder('PRECIO', { atributosNuevos: con(E.precio) });
if (PREGUNTA_PRECIO.test(texto)) return responder('PRECIO');

// 11. Cualquier otra cosa: pasa a Sergio.
return responder('DERIVAR', { pasarASergio: true });
